$cases = [
    "memory"  => fopen("php://memory", "w+"),
    "temp"    => fopen("php://temp", "w+"),
    "stdout"  => fopen("php://output", "w"),
    "data"    => fopen("data://text/plain,hello", "r"),
    "file"    => fopen(tempnam(sys_get_temp_dir(), "fl"), "w+"),
];

foreach ($cases as $name => $handle) {
    $out = null;
    $r = @flock($handle, LOCK_EX, $out);
    echo $name, " => ", var_export($r, true), " would-block=", var_export($out, true), "\n";
    $u = @flock($handle, LOCK_UN);
    echo $name, " unlock => ", var_export($u, true), "\n";
}
